package com.nanless.paperdigest.data

import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.File

/** Expected outputs were generated by the unmodified official website tag-core, not by this port. */
class WebsiteTaxonomySharedFixtureTest {
    private fun fixture():JSONObject {
        val root=generateSequence(File(System.getProperty("user.dir")).absoluteFile){it.parentFile}.first{File(it,"tests/fixtures/workbench-website-taxonomy-golden.json").isFile}
        return JSONObject(File(root,"tests/fixtures/workbench-website-taxonomy-golden.json").readText())
    }
    @Test fun websiteGoldenRecordsAgreeOnIssuedLabelsCurrentPathsAndFailureStates(){
        val f=fixture();val taxonomy=WebsiteTaxonomy.parse(f.getJSONObject("display"));val cases=f.getJSONArray("cases");assertEquals(14,cases.length())
        for(i in 0 until cases.length()) {
            val c=cases.getJSONObject(i);val expected=c.getJSONObject("expected");val result=taxonomy.classify(c.getJSONObject("record"));val name=c.getString("name")
            if(expected.optBoolean("error")){assertEquals(name,"invalid",result.status);assertTrue(name,result.concepts.isEmpty());continue}
            assertEquals(name,expected.getString("status"),result.status)
            assertEquals(name,expected.getJSONArray("issuedConceptIds").strings(),result.issuedConcepts.map{it.id})
            assertEquals(name,expected.getJSONArray("issuedLabels").strings(),result.issuedConcepts.map{it.label})
            val navigation=expected.getJSONArray("navigation")
            assertEquals(name,navigation.length(),result.concepts.size)
            for(j in 0 until navigation.length()) {
                val e=navigation.getJSONObject(j);val node=result.concepts[j];assertEquals(name,e.getString("id"),node.id);assertEquals(name,e.getString("label"),node.label);assertEquals(name,e.getString("facet"),node.facet)
                val path=e.getJSONArray("path").objects();assertEquals(name,path.map{it.getString("id")},node.ancestors+node.id);assertEquals(name,path.map{it.getString("label")},(node.ancestors+node.id).map{taxonomy.nodes.getValue(it).label})
            }
        }
    }
}
